'use strict';const API_URL = '/api/ejercicios';const form = document.querySelector('#exercise-form');const list = document.querySelector('#exercise-list');const emptyState = document.querySelector('#empty-state');const count = document.querySelector('#record-count');const status = document.querySelector('#status');const numberFormat = new Intl.NumberFormat('es-MX',{maximumFractionDigits: 2});const submitButton = form.querySelector('button[type="submit"]');let exercises =[];function validExercise(item){return item && typeof item.name === 'string' && item.name.trim().length > 0 && item.name.length <= 80 && Number.isInteger(item.sets)&& item.sets >= 1 && item.sets <= 1000 && Number.isInteger(item.reps)&& item.reps >= 1 && item.reps <= 10000 && Number.isFinite(item.weight)&& item.weight >= 0 && item.weight <= 10000;}async function request(url,options ={}){let response;try{response = await fetch(url,{...options,cache: 'no-store'});}catch{throw new Error('No se pudo conectar con el servidor. Comprueba la conexión e inténtalo de nuevo.');}if(!response.ok){const data = await response.json().catch(()=>({}));throw new Error(data.error || 'No se pudo completar la operación. Inténtalo de nuevo.');}if(response.status === 204)return null;return response.json();}function fromDatabase(row){const exercise ={id: row.id,name: row.nombre,sets: row.series,reps: row.repeticiones,weight: row.peso};if(!Number.isInteger(exercise.id)|| exercise.id < 1 || !validExercise(exercise)){throw new Error('El servidor devolvió un registro no válido.');}return exercise;}async function loadExercises(){submitButton.disabled = true;emptyState.hidden = true;status.textContent = 'Cargando ejercicios…';try{const rows = await request(API_URL);if(!Array.isArray(rows))throw new Error('El servidor devolvió una respuesta no válida.');exercises = rows.map(fromDatabase);renderExercises();submitButton.disabled = false;status.textContent = '';}catch(error){status.textContent = `${error.message} Actualiza la página para volver a cargar los registros.`;}}function renderExercises(){list.replaceChildren();emptyState.hidden = exercises.length > 0;count.textContent = `${exercises.length} ${exercises.length === 1 ? 'registro' : 'registros'}`;for(const exercise of exercises){const card = document.createElement('li');card.className = 'exercise-card';const heading = document.createElement('div');heading.className = 'card-heading';const title = document.createElement('h3');title.textContent = exercise.name;const remove = document.createElement('button');remove.type = 'button';remove.className = 'delete';remove.textContent = 'Eliminar';remove.setAttribute('aria-label',`Eliminar ${exercise.name}`);remove.addEventListener('click',async()=>{if(remove.disabled)return;remove.disabled = true;try{await request(`${API_URL}/${exercise.id}`,{method: 'DELETE'});const index = exercises.findIndex((item)=> item.id === exercise.id);exercises = exercises.filter((item)=> item.id !== exercise.id);renderExercises();status.textContent = `Se eliminó ${exercise.name}.`;const buttons = list.querySelectorAll('.delete');(buttons[Math.min(index,buttons.length - 1)]|| form.elements.name).focus();}catch(error){status.textContent = error.message;remove.disabled = false;}});heading.append(title,remove);const metrics = document.createElement('dl');metrics.className = 'metrics';for(const[label,value]of[['Series',exercise.sets],['Repeticiones',exercise.reps],['Peso (kg)',exercise.weight]]){const group = document.createElement('div');const term = document.createElement('dt');term.textContent = label;const detail = document.createElement('dd');detail.textContent = numberFormat.format(value);group.append(term,detail);metrics.append(group);}card.append(heading,metrics);list.append(card);}}form.addEventListener('submit',async(event)=>{event.preventDefault();if(submitButton.disabled)return;const nameInput = form.elements.name;nameInput.setCustomValidity(nameInput.value.trim()? '' : 'Escribe el nombre del ejercicio.');if(!form.reportValidity())return;const exercise ={name: nameInput.value.trim(),sets: Number(form.elements.sets.value),reps: Number(form.elements.reps.value),weight: Number(form.elements.weight.value),};if(!validExercise(exercise))return;submitButton.disabled = true;try{const row = await request(API_URL,{method: 'POST',headers:{'Content-Type': 'application/json'},body: JSON.stringify({nombre: exercise.name,series: exercise.sets,repeticiones: exercise.reps,peso: exercise.weight}),});exercises =[fromDatabase(row),...exercises];renderExercises();form.reset();nameInput.focus();status.textContent = `${exercise.name} se registró correctamente.`;}catch(error){status.textContent = error.message;}finally{submitButton.disabled = false;}});form.elements.name.addEventListener('input',()=> form.elements.name.setCustomValidity(''));loadExercises();